package com.motionwall.app

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/** V0.1 tests the version metadata generated by the Android Gradle plugin. */
class VersionTest {
    @Test
    fun initialVersionNameIsCorrect() {
        assertEquals("0.1.0", BuildConfig.VERSION_NAME)
    }

    @Test
    fun initialVersionCodeIsOne() {
        assertEquals(1, BuildConfig.VERSION_CODE)
    }

    @Test
    fun applicationIdUsesMotionWallNamespace() {
        assertTrue(BuildConfig.APPLICATION_ID.startsWith("com.motionwall.app"))
    }
}
